import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Combate Legacy y Modern","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/legacy-and-modern.md","filePath":"es/guide/combat/legacy-and-modern.md"}'),i={name:"es/guide/combat/legacy-and-modern.md"};function r(d,a,c,s,l,p){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="legacy-and-modern-combat" tabindex="-1">Combate Legacy y Modern <a class="header-anchor" href="#legacy-and-modern-combat" aria-label="Enlace permanente a &quot;Combate Legacy y Modern&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Nuevas acciones de los dos modos no implementadas.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Ambos modos comienzan seleccionando un objetivo y comparten las reglas básicas de las armas.</li><li>Legacy ataca automáticamente; Modern permite elegir cuándo empieza una acción disponible.</li><li>Modern es la dirección experimental preferida; Legacy sigue siendo una alternativa accesible y familiar.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspecto</th><th>Significado</th></tr></thead><tbody><tr><td>Ataque básico</td><td>Legacy sigue una cadencia automática; Modern espera tu orden.</td></tr><tr><td>Special Attack ofensivo</td><td>Pon en cola el próximo golpe válido en Legacy; inicia una acción disponible en Modern.</td></tr><tr><td>Defensa manual</td><td>Disponible en ambos modos, sujeta a preparación, resistencia y recuperación.</td></tr><tr><td>Límites compartidos</td><td>Empezar ahora no significa acertar al instante ni saltarse la recuperación.</td></tr><tr><td>Arquería</td><td>Los disparos normales no exigen un minijuego de ritmo. Modern controla la suelta; ciertos disparos especiales pueden compartir una prueba de precisión temporal.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Syrolands</th></tr></thead><tbody><tr><td>Cadencia automática de ataque</td><td>Legacy mantiene el enfoque conocido; Modern añade el inicio deliberado.</td></tr><tr><td>Los ataques especiales varían según la época</td><td>Las acciones aprendidas comparten costes y fases entre los dos modos propuestos.</td></tr></tbody></table><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Pon Thrust en cola para el siguiente golpe válido de Legacy, o inícialo en Modern cuando aparezca la oportunidad. La misma acción consume resistencia y deja una recuperación posterior.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Special Attacks</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/legacy-and-modern.html">Leer la especificación de diseño completa</a></p>',15)])])}const h=e(i,[["render",r]]);export{u as __pageData,h as default};
